import 'package:flutter/material.dart';
import 'package:provider/provider.dart';
import '../../services/devhub_api.dart';
import '../../core/app_theme.dart';
import '../../widgets/devhub_widgets.dart';
class DevelopersScreen extends StatefulWidget{const DevelopersScreen({super.key});@override State<DevelopersScreen> createState()=>_DevelopersScreenState();}
class _DevelopersScreenState extends State<DevelopersScreen>{final q=TextEditingController();List<dynamic> results=[];bool loading=false;String error='';
 Future<void> search()async{setState(()=>loading=true);try{final data=await context.read<DevHubApi>().searchDevelopers(q:q.text.trim());results=(data['users']??data['developers']??data['results']??[]) as List;error='';}catch(e){error=e.toString();}finally{if(mounted)setState(()=>loading=false);}}
 @override Widget build(BuildContext context)=>ListView(padding:const EdgeInsets.all(18),children:[Text('Find developers',style:Theme.of(context).textTheme.headlineMedium),const SizedBox(height:5),const Text('Discover people with complementary skills and invite them to build together.',style:TextStyle(color:AppColors.muted)),const SizedBox(height:18),Row(children:[Expanded(child:TextField(controller:q,onSubmitted:(_)=>search(),decoration:const InputDecoration(prefixIcon:Icon(Icons.search),hintText:'Name, role or skill'))),const SizedBox(width:8),IconButton.filled(onPressed:loading?null:search,icon:const Icon(Icons.search))]),const SizedBox(height:18),if(loading)const Center(child:CircularProgressIndicator()),if(error.isNotEmpty)Text(error,style:const TextStyle(color:AppColors.red)),...results.map((raw){final m=Map<String,dynamic>.from(raw);final user=Map<String,dynamic>.from(m['user']??m);final skills=List<dynamic>.from(m['skills']??user['skills']??[]);return Padding(padding:const EdgeInsets.only(bottom:12),child:Panel(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(children:[InitialAvatar(name:'${user['name']??user['username']??'D'}',url:'${user['avatarUrl']??''}'),const SizedBox(width:12),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('${user['name']??user['username']??'Developer'}',style:Theme.of(context).textTheme.titleMedium),Text('@${user['username']??''}',style:const TextStyle(color:AppColors.muted))])),if(m['score']!=null)Text('${(m['score'] as num).round()}% match',style:const TextStyle(color:AppColors.green,fontWeight:FontWeight.bold))]),if('${user['bio']??''}'.isNotEmpty)Padding(padding:const EdgeInsets.only(top:10),child:Text('${user['bio']}',maxLines:3,overflow:TextOverflow.ellipsis,style:const TextStyle(color:AppColors.muted))),const SizedBox(height:10),Wrap(spacing:6,runSpacing:6,children:skills.take(7).map((s)=>SkillPill(s is Map?'${s['name']}':'$s')).toList()),const SizedBox(height:12),Align(alignment:Alignment.centerRight,child:OutlinedButton.icon(onPressed:()=>_invite(context,'${user['_id']??''}','${user['username']??''}'),icon:const Icon(Icons.handshake_outlined,size:17),label:const Text('Collaborate')))])));}),if(results.isEmpty&&!loading&&error.isEmpty)const Panel(child:Text('Search for a developer to see matching profiles.',style:TextStyle(color:AppColors.muted)))]);
 Future<void> _invite(BuildContext context,String id,String username)async{final controller=TextEditingController(text:'Hi! I would love to connect and explore a collaboration.');final message=await showDialog<String>(context:context,builder:(ctx)=>AlertDialog(backgroundColor:AppColors.card,title:Text('Invite @$username'),content:TextField(controller:controller,maxLines:4,decoration:const InputDecoration(labelText:'Message')),actions:[TextButton(onPressed:()=>Navigator.pop(ctx),child:const Text('Cancel')),ElevatedButton(onPressed:()=>Navigator.pop(ctx,controller.text),child:const Text('Send'))]));if(message==null)return;try{await context.read<DevHubApi>().sendRequest({'receiverId':id.isEmpty?null:id,'receiverUsername':username,'message':message});if(context.mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Collaboration request sent')));}catch(e){if(context.mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.toString())));}}
}
